export function normalizeForNgCheck(raw: string): string {
  return raw
    .normalize("NFKC")
    .toLowerCase()
    .replace(/[\s\u3000_\-・･./\\|'`~!@#$%^&*()+=\[\]{};:,<>?？！。、「」『』（）]/g, "");
}

const NORMALIZED_NG_WORDS = new Set(
  NG_WORDS.map(normalizeForNgCheck).filter((w) => w.length >= 2),
);

/** true if the whole (normalized) name equals a blocked term */
export function containsNgWord(raw: string): boolean {
  const normalized = normalizeForNgCheck(raw);
  if (!normalized) return false;
  return NORMALIZED_NG_WORDS.has(normalized);
}
